#include <stdio.h>

int main(void) {
    char names[2][16] = {"阿花", "大肥鱼"};
    char *row[3];

    for (int i = 0; i < 3; i++) {
        if (i < 2) {
            row[i] = names[i];
        } else {
            row[i] = NULL;
        }
    }

    int count = 0;
    for (int i = 0; i < 3; i++) {
        if (row[i] == NULL) {
            printf("第 %d 张：空\n", i);
        } else {
            printf("第 %d 张：%s\n", i, row[i]);
            count++;
        }
    }
    printf("能用的牌子：%d 张\n", count);

    return 0;
}

